import React, { useRef, useEffect, useImperativeHandle, forwardRef } from 'react';
import { LyricData, Word, AudioVisualizerData } from '../types';

interface CanvasVideoRendererProps {
  data: LyricData;
}

export interface CanvasVideoRendererRef {
  drawFrame: (time: number, analysisData: AudioVisualizerData) => void;
  canvas: HTMLCanvasElement | null;
}

// 16:9 Full HD Canvas
const CANVAS_WIDTH = 1920;
const CANVAS_HEIGHT = 1080;

interface Particle {
  id: number;
  x: number;
  y: number;
  vx: number;
  vy: number;
  size: number;
  color: string;
  alpha: number;
  phase: number;
}

const COLORS = ['#22d3ee', '#a855f7', '#ffffff', '#38bdf8', '#c084fc'];

export const CanvasVideoRenderer = forwardRef<CanvasVideoRendererRef, CanvasVideoRendererProps>(({
  data
}, ref) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const wordsByLineCache = useRef<Map<string, Word[][]>>(new Map());

  // Deterministic Particles
  const particlesRef = useRef<Particle[]>([]);

  // Initialize particles strictly once
  useEffect(() => {
    if (particlesRef.current.length === 0) {
      // Seeded-like generation for deterministic behavior
      for (let i = 0; i < 150; i++) {
        particlesRef.current.push({
          id: i,
          x: (Math.sin(i * 12.34) * 0.5 + 0.5) * CANVAS_WIDTH,
          y: (Math.cos(i * 56.78) * 0.5 + 0.5) * CANVAS_HEIGHT,
          vx: (Math.sin(i * 99.11) - 0.5) * 1.5,
          vy: (Math.cos(i * 11.22) - 0.5) * 1.5,
          size: (Math.sin(i) * 0.5 + 0.5) * 4 + 1,
          color: COLORS[i % COLORS.length],
          alpha: (Math.sin(i * 3) * 0.5 + 0.5) * 0.5 + 0.2,
          phase: Math.random() * Math.PI * 2
        });
      }
    }
  }, []);

  const getLines = (segmentId: string, words: Word[]): Word[][] => {
    if (wordsByLineCache.current.has(segmentId)) {
      return wordsByLineCache.current.get(segmentId)!;
    }
    const linesMap: Record<number, Word[]> = {};
    words.forEach(w => {
      if (!linesMap[w.line_number]) linesMap[w.line_number] = [];
      linesMap[w.line_number].push(w);
    });
    const result = Object.values(linesMap);
    wordsByLineCache.current.set(segmentId, result);
    return result;
  };

  const drawScene = (time: number, analysis: AudioVisualizerData) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d', { alpha: false });
    if (!ctx) return;

    const { bass, mid, high, raw } = analysis;

    // --- 0. Pre-Calculation: Active Segment ---
    const activeSegmentIndex = data.segments.findIndex(
      (seg) => time >= seg.start - 1.0 && time <= seg.end + 1.0
    );
    const activeSegment = activeSegmentIndex !== -1 ? data.segments[activeSegmentIndex] : null;

    // --- 1. Background (Screen Space) ---
    // Drawn before camera transform to ensure full coverage
    ctx.setTransform(1, 0, 0, 1, 0, 0); // Reset transform
    ctx.fillStyle = '#050505';
    ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    // Pulsing Gradient Background
    const centerX = CANVAS_WIDTH / 2;
    const centerY = CANVAS_HEIGHT / 2;
    // Radius pulses with bass
    const bgRadius = CANVAS_WIDTH * (0.6 + bass * 0.3);
    const bgGradient = ctx.createRadialGradient(centerX, centerY, 0, centerX, centerY, bgRadius);
    const bgOpacity = 0.15 + (bass * 0.25);

    bgGradient.addColorStop(0, `rgba(34, 211, 238, ${bgOpacity})`);
    bgGradient.addColorStop(0.5, `rgba(168, 85, 247, ${bgOpacity * 0.5})`);
    bgGradient.addColorStop(1, 'rgba(0, 0, 0, 0)');

    ctx.fillStyle = bgGradient;
    ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    // --- 2. Camera Setup ---
    ctx.save(); // Save screen space state for restoration later

    // Camera Parameters Calculation
    // A. Zoom: Pulse on Bass + Slow Breathing + Segment Focus
    const baseZoom = 1.05; // Slight overscan to hide edges during rotation
    const beatZoom = bass * 0.08; 
    const breathZoom = Math.sin(time * 0.5) * 0.02;
    const totalZoom = baseZoom + beatZoom + breathZoom;

    // B. Rotation: Tilt based on segment index (Alternating cuts) + slow drift
    // Even segments tilt left, Odd segments tilt right
    let targetTilt = 0;
    if (activeSegmentIndex !== -1) {
        // Toggle tilt direction based on segment parity
        targetTilt = (activeSegmentIndex % 2 === 0 ? 1 : -1) * 0.03; // ~1.7 degrees
    }
    const driftRot = Math.sin(time * 0.2) * 0.015;
    const totalRot = targetTilt + driftRot;

    // C. Pan: Drift X/Y for organic feel
    const panX = Math.sin(time * 0.3) * 30;
    const panY = Math.cos(time * 0.4) * 20;

    // Apply Camera Transform:
    // 1. Move origin to center
    // 2. Rotate
    // 3. Scale (Zoom)
    // 4. Move origin back (including camera pan offset)
    ctx.translate(CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2);
    ctx.rotate(totalRot);
    ctx.scale(totalZoom, totalZoom);
    ctx.translate(-CANVAS_WIDTH / 2 - panX, -CANVAS_HEIGHT / 2 - panY);

    // --- 3. World Elements (Particles, Waves, Text) ---

    // A. Particles
    particlesRef.current.forEach(p => {
        // Deterministic position logic using time
        let nx = p.x + (p.vx * time * 60 * 0.5); 
        let ny = p.y + (p.vy * time * 60 * 0.5);

        // Audio reactivity: Particles float/vibrate with Mid range
        ny -= mid * 50 * Math.sin(time + p.id);

        // Wrap around canvas dimensions
        nx = ((nx % CANVAS_WIDTH) + CANVAS_WIDTH) % CANVAS_WIDTH;
        ny = ((ny % CANVAS_HEIGHT) + CANVAS_HEIGHT) % CANVAS_HEIGHT;

        ctx.beginPath();
        const size = p.size * (1 + high * 2); // Pulse size with Highs
        ctx.arc(nx, ny, size, 0, Math.PI * 2);
        ctx.fillStyle = p.color;

        // Flash alpha with Mids
        const flash = Math.sin(time * 5 + p.phase) * mid; 
        ctx.globalAlpha = Math.min(1, Math.max(0, p.alpha + flash));
        ctx.fill();
        ctx.globalAlpha = 1.0;
    });

    // B. Wave Effect
    ctx.save();
    ctx.beginPath();
    ctx.moveTo(-100, CANVAS_HEIGHT / 2); // Start off-screen
    for (let x = -100; x <= CANVAS_WIDTH + 100; x += 40) {
        // Compound sine wave modulated by Bass and Mid
        const yOffset = Math.sin(x * 0.005 + time * 2) * (50 + bass * 120);
        const yOffset2 = Math.cos(x * 0.01 - time) * (30 + mid * 60);
        ctx.lineTo(x, CANVAS_HEIGHT / 2 + yOffset + yOffset2);
    }
    ctx.strokeStyle = `rgba(255, 255, 255, ${0.05 + bass * 0.1})`;
    ctx.lineWidth = 2 + bass * 5;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.stroke();
    ctx.restore();

    // C. Typography (Lyrics)
    if (activeSegment) {
      const lines = getLines(activeSegment.id, activeSegment.words);
      const lineHeight = 130;
      const totalHeight = lines.length * lineHeight;
      // Center vertically in World Space
      const startY = (CANVAS_HEIGHT - totalHeight) / 2 + lineHeight / 2;
      const baseFontSize = 100;

      ctx.font = `900 ${baseFontSize}px "Montserrat", sans-serif`;

      lines.forEach((lineWords, lineIndex) => {
         // Measure total line width for centering
         let lineWidth = 0;
         const wordSpacings: number[] = [];

         lineWords.forEach((word) => {
             const width = ctx.measureText(word.word).width;
             wordSpacings.push(width);
             lineWidth += width + 40; // Gap between words
         });
         lineWidth -= 40; 

         let currentX = (CANVAS_WIDTH - lineWidth) / 2;
         const currentY = startY + (lineIndex * lineHeight);

         lineWords.forEach((word, wIdx) => {
             const width = wordSpacings[wIdx];
             const isPast = time > word.end;
             const isFuture = time < word.start;
             const isActive = !isPast && !isFuture;

             ctx.save();
             // Move to center of word for scaling/rotation
             ctx.translate(currentX + width / 2, currentY);

             if (isActive) {
               ctx.shadowColor = "rgba(56, 189, 248, 0.9)";
               ctx.shadowBlur = 40 + (bass * 30); 
               ctx.fillStyle = "#22d3ee";
               // Active Word Pop
               const scale = 1.1 + (bass * 0.15);
               ctx.scale(scale, scale);
             } else if (isFuture) {
               // Coming soon animation
               const diff = word.start - time;
               if (diff < 0.6) {
                  const progress = 1 - (diff / 0.6);
                  ctx.globalAlpha = 0.2 + (progress * 0.8);
                  const enterScale = 0.8 + (0.2 * progress);
                  ctx.scale(enterScale, enterScale);
                  ctx.translate(0, (1-progress) * 40); // Slide up
               } else {
                  ctx.globalAlpha = 0; 
               }
               ctx.fillStyle = "#ffffff";
             } else {
               // Past words fade out
               ctx.globalAlpha = 0.3;
               ctx.fillStyle = "#9ca3af";
               ctx.scale(1, 1);
             }

             if (ctx.globalAlpha > 0.01) {
                 ctx.textAlign = 'center';
                 ctx.textBaseline = 'middle';
                 ctx.fillText(word.word, 0, 0);
             }

             ctx.restore();
             currentX += width + 40;
         });
      });
    }

    // Restore coordinate system to Screen Space for HUD elements
    ctx.restore();

    // --- 4. HUD / Post-Process (Screen Space) ---
    // These elements should not be affected by camera shake/zoom

    // Vignette
    const vignette = ctx.createRadialGradient(
        CANVAS_WIDTH/2, CANVAS_HEIGHT/2, CANVAS_HEIGHT/2, 
        CANVAS_WIDTH/2, CANVAS_HEIGHT/2, CANVAS_WIDTH/1.2
    );
    vignette.addColorStop(0, 'rgba(0,0,0,0)');
    vignette.addColorStop(1, 'rgba(0,0,0,0.6)');
    ctx.fillStyle = vignette;
    ctx.fillRect(0,0, CANVAS_WIDTH, CANVAS_HEIGHT);

    // Spectrum Bars (Fixed to bottom of screen)
    const bufferLength = raw.length;
    // Only display first 64 bins (bass/mid heavy)
    const displayCount = Math.min(bufferLength, 64);
    const barWidth = (CANVAS_WIDTH / displayCount) * 1.2;
    let xPos = 0;
    // Center the bars horizontally
    const startX = (CANVAS_WIDTH - (displayCount * (barWidth + 2))) / 2;

    for (let i = 0; i < displayCount; i++) {
        const value = raw[i];
        // Power curve to exaggerate peaks
        const barHeight = Math.pow(value / 255, 1.8) * (CANVAS_HEIGHT * 0.3);

        if (barHeight > 5) {
            const hue = 180 + (i / displayCount) * 120 + (bass * 30);
            const sat = 80 + (mid * 20);
            const light = 50 + (high * 30);

            ctx.fillStyle = `hsla(${hue}, ${sat}%, ${light}%, 0.6)`;

            // Bottom Bar
            ctx.fillRect(startX + xPos, CANVAS_HEIGHT - barHeight, barWidth, barHeight);

            // Subtle Reflection
            ctx.fillStyle = `hsla(${hue}, ${sat}%, ${light}%, 0.15)`;
            ctx.fillRect(startX + xPos, CANVAS_HEIGHT - barHeight - (barHeight * 0.2), barWidth, barHeight * 0.2);
        }
        xPos += barWidth + 2;
    }
  };

  useImperativeHandle(ref, () => ({
    drawFrame: drawScene,
    canvas: canvasRef.current
  }));

  return (
    <canvas
      ref={canvasRef}
      width={CANVAS_WIDTH}
      height={CANVAS_HEIGHT}
      className="w-full h-full object-contain"
    />
  );
});

CanvasVideoRenderer.displayName = 'CanvasVideoRenderer';

To improve the stability of the rendering process and address the issue where it hangs at 100%, I will modify `App.tsx`.

**Changes implemented:**
1.  **Increased Stability**: Added more frequent "yields" (`setTimeout`) to the main thread during the rendering loop. This slows down the process slightly (as requested) but ensures the browser doesn't freeze and garbage collection can run, preventing crashes on lower-end devices.
2.  **Clearer Status**: Added a dedicated `Finalizing...` visual state. When the progress hits 100%, the internal state switches to `encoding` (displayed as "FINALIZING") while the heavy `flush()` and `muxer.finalize()` operations complete. This reassures the user that the app hasn't crashed.
3.  **Audio Yielding**: Added yielding during the audio encoding phase as well, which was previously a single blocking loop.

